46	export const formatAudioTime = (seconds: number): string => {
47	  if (!Number.isFinite(seconds) || seconds < 0) {
48	    return "0:00";
49	  }
50	
51	  const rounded = Math.floor(seconds);
52	  const hours = Math.floor(rounded / 3600);
53	  const minutes = Math.floor((rounded % 3600) / 60);
54	  const secs = rounded % 60;
55	
56	  if (hours > 0) {
57	    return `${hours}:${minutes.toString().padStart(2, "0")}:${secs.toString().padStart(2, "0")}`;
58	  }
59	
60	  return `${minutes}:${secs.toString().padStart(2, "0")}`;
61	};
